"""Render the final Russian report from bounded, identity-checked exports."""
import collections
from datetime import datetime, timezone
import json
from pathlib import Path

BASE=Path(__file__).resolve().parent
PREFIX='slice::sort::shared::smallsort::verify::'

def fmt(n, places=3):
    return 'NA' if n is None else f'{n:.{places}f}'

def short(name):
    return name.removeprefix(PREFIX)

def main():
    m=json.loads((BASE/'measurements.json').read_text())
    r=json.loads((BASE/'report-metrics.json').read_text())
    session=json.loads((BASE/'session.json').read_text())
    full=m['builds']['autoharness']
    fm=next(b for b in r['builds'] if b['label']=='autoharness')
    p=BASE.parent/'RESULT-C3C.md'
    text=p.read_text().split('<!-- RUN-RESULTS -->')[0]
    text=text.replace('Статус выполнения: пробы отправлены; полного результата пока нет. Финальный исход будет установлен по\nbounded summary, inventory и peaks.', 'Итог: цель ordinary≤300с на macOS не принята. Полный GCB job имеет статус '+fm['cloud_status']+' / '+fm['kani_status']+';\nточные наблюдения и ограничения приведены ниже. Приёмка требует нового П-6.')
    a=['## Сборки и CI-budget','', 'Источник времени и стоимости — Cloud startTime/finishTime (`*.status.json`), ledger с округлением вверх', 'до минуты по$0.0135/min. Это расчётный ledger, не счёт billing. Kani wall — отдельный GNU time,', 'не wall всей сборки. Суммы VT включают только наблюдаемые времена, без восстановления TIMEOUT/NOT_RUN.', '', '| Запуск | Build UUID | Head SHA | Cloud / summary | SUCCESS / всего | Cloud wall, с | Kani wall | Ledger USD |','|---|---|---|---|---:|---:|---|---:|']
    for b in r['builds']:
        a.append(f"| {b['label']} | {b['build_id']} | {b['source_sha'][:12]} | {b['cloud_status']} / {b['kani_status']} | {b['success_rows']} / {b['row_count']} | {fmt(b['cloud_wall_s'],1)} | {b['kani_command_wall'] or 'NA'} | {fmt(b['used_ledger_cost_usd'],4)} |")
    a+=['', '| Запуск | Driver HWM, GiB | CBMC HWM, GiB | Отдельный solver HWM | Одновременная RSS-сумма, GiB @с |','|---|---:|---:|---:|---:|']
    for b in r['builds']:
        gib=lambda v:fmt(None if v is None else v/1048576,2)
        a.append(f"| {b['label']} | {gib(b['driver_hwm_kb'])} | {gib(b['cbmc_hwm_kb'])} | {'; '.join(f'{name} {v["hwm_kb"]/1048576:.3f}GiB @{v["peak_s"]}' for name,v in (b['solver_hwm'] or {}).items()) or 'NA'} | {gib(b['sampled_total_rss_peak_kb'])} @{b['sampled_total_rss_peak_s'] if b['sampled_total_rss_peak_s'] is not None else 'NA'} |")
    total=sum(b['used_ledger_cost_usd'] or 0 for b in r['builds'])
    a+=['',f"Всего {len(session['builds'])}/8 сборок, расчётный ledger ${total:.4f}/$10; глобальный CAP_USD=63.96 не изменён.", 'Резервы и исходные guards — [session](c3c/session.json), `budget-before-*` / `budget-final.txt`.', 'Источники каждой цифры, exact SHA, все statuses, counters и process summaries:', '[подробные таблицы](c3c/report-tables.md), [derived measurements](c3c/measurements.json), [bounded evidence](c3c/evidence/).', '', '| Job / источник | Все строки / сумма VT, с | SmallSort строки / сумма VT, с | Доля SmallSort | Wall, с | RSS-пик, GiB | Failures / timeouts |','|---|---:|---:|---:|---:|---:|---|', '| P6 Mac, предоставленный TSV run40748125754 | 2313 /28518.6 | 322 /25367.5 | 88.95% | NA | NA | 3T600 по TASK, вне сумм TSV |', f"| GCB full `{full['build_id']}` | {full['all']['count']} /{fmt(full['all']['sum_observed_verification_s'])} | {full['smallsort']['count']} /{fmt(full['smallsort']['sum_observed_verification_s'])} | {fmt(None if full['smallsort_share_of_observed_verification_time'] is None else full['smallsort_share_of_observed_verification_time']*100,2)}% | {fmt(fm['cloud_wall_s'],1)} | {gib(fm['sampled_total_rss_peak_kb'])} | {json.dumps(full['all']['statuses'])} |", '', 'У P6 нет исходных wall/RAM/USD; сравнивать суммы VT с wall нельзя. Наблюдаемое изменение сумм VT', 'не является matched улучшением whole job: baseline full отсутствует, число моделей изменилось, цензура различается.', '', '## Единственный полный autoharness','', f"Build `{full['build_id']}`, head `{full['head_sha']}`, library `{session['candidate_library_sha']}`.", f"Gate={full['gate']}; summary={full['summary_status']}; native inventory={len(full['ordinary_inventory'])} ordinary.", f"SmallSort statuses: {json.dumps(full['smallsort']['statuses'])}.", f"Inventory/source prediction: missing={len(full['inventory_prediction_missing'])}, extra={len(full['inventory_prediction_extra'])}; results missing={len(full['inventory_results_missing'])}, duplicate={len(full['inventory_results_duplicated'])}.", 'Все native inventory страницы проверены по request/head/build identity, offset/count/next_offset и names SHA256.', 'Старый parser полного snapshot и его gate не переписывались после запуска. Любой INCONSISTENT/PARTIAL', 'сохраняется как ограничение evidence, а не превращается в PASS. Источники — `autoharness.*` в evidence;', 'доступные machine/cgroup/OOM/dmesg сведения сохранены в `autoharness.peaks.txt`.', 'В историческом summary строка per-harness timeout270min — ошибка подписи общего бюджета. Фактически literal workflow использовал10m на гармонику; подпись исправлена отдельным lane-коммитом `3184754242` с regression test.', 'Bounded machine view: inventory/setup заняли3186с после validate; остаток verify_budget14454с. GNU time при общем timeout не разобран, поэтому Kani wall=NA; это не потеря Cloud wall.', 'Пик13.54GiB — sampled RSS, driver8.06GiB, CBMC4.34GiB; отдельный kissat0.043GiB встречался в других std-моделях, SmallSort K удалён. Cgroup events в snapshot недоступны; dmesg=none_seen не доказывает отсутствие OOM.', 'Native inventory421 подтверждён, но только238 SmallSort моделей начаты:233SUCCESS,2T600,3MISSING_RESULT;183 не имеют result rows в этом частичном прогоне. Они не названы NOT_RUN, diagnostics не подставлены вместо full результатов.', 'RSS-пик относится к стандартной GCB машине без swap; это наблюдение не гарантирует успех GitHub.', '', '## Opt-in covers-аудит','']
    audit=r['controls_audit']
    a += [f"Состояние: {audit['state']}; выборочный covers-аудит passed={audit.get('sample_audit_passed',False)} (Mac acceptance=false).", 'Проверяется тот же library-кандидат, cfg `kani_smallsort_controls`. Выборка по correct/merge/network', 'и оба фиксированных correct R маршрута; это выборка измеренного fd854ca754 (100 sites); финальный source fix e45cfc7250 не проходил CI.', 'Успех requires SUCCESS, covers_total>0 и covers_satisfied==covers_total для каждой выбранной строки.', 'Фактически9SUCCESS/1TIMEOUT180: correct::contract_insert_tail_u8_prefix не завершён. Семь SUCCESS harnesses имеют все covers SAT; оба fixed correct R u8N14 имеют1/2. Поэтому выборочный аудит НЕ ПРИНЯТ.', 'Оба недостающих R cover относятся к противоположной константной ветви (stable/general); это объясняет UNSAT, но не превращает аудит в PASS. Это source-объяснение по константной ветви; terse log не дал property IDs (bounded grep: no match), поэтому отдельная трасса свойств не заявляется. Final source fix e45cfc7250 описан выше; его повторный аудит не выполнен:8/8 builds.', 'Необъяснённые UNSAT/UNREACHABLE не исключаются из критерия. Ordinary proofs остались ordinary.', '[Построчные counts и источник](c3c/report-tables.md#аудит-controls).', '', '## Оставшиеся риски и варианты владельцу','']
    flags=collections.Counter(flag for row in m['ordinary_risk_register'] for flag in row['flags'])
    a += [f"Полный реестр содержит {len(m['ordinary_risk_register'])} native ordinary строк: [risk-register.tsv](c3c/risk-register.tsv).", 'Числа флагов (пересекаются): '+', '.join(f'{k}={v}' for k,v in sorted(flags.items()))+'.', 'NA означает отсутствие прогноза, а не выполнение цели300с. Оценки и traceability сохранены для всех', 'ordinary, включая не входившие в исторические тяжёлые18 доменов.', '', '| Ordinary (verify::) | GCB status / VT, с | Mac point, с | Mac stress, с |','|---|---:|---:|---:|']
    severe=[x for x in m['ordinary_risk_register'] if x['status'] not in ('SUCCESS','NO_RESULT_ROW','MISSING_OR_DUPLICATE') or any(f in x['flags'] for f in ('MAC_POINT_OVER_300','MAC_OBSERVED_TAIL_OVER_300','MAC_CENSORED_LOWER_TRANSFER_OVER_300'))]
    for x in severe:
        a.append(f"| {short(x['name'])} | {x['status']} / {fmt(x['gcb_time_s'])} | {fmt(x['mac_point_forecast_s'])} | {fmt(x['mac_observed_tail_transfer_s'])} |")
    a+=['', 'Именованный перечень теряемых доменов, source coordinates и зависимых композиционных утверждений', 'для каждой строки с проблемой времени/результата, а также для преемников исторических Mac T600:', '[owner-risk-options.tsv](c3c/owner-risk-options.tsv). **Ни один перенос proof в opt-in не применён.**', 'Сохраняются full-width входы, все offsets/routes и прежние assertions; соседний N/T или иной allocation', 'не заменяет пропущенный контракт. В частности, потеря merge u64 N16 затронула бы предпосылку обеих', 'ordinary upper-route proofs, использующих verified merge stub; existing allocation-locality gaps остаются.', '', 'Варианты владельцу: новый П-6 для всего кандидата; продолжить точные разбиения тяжёлых доменов', 'с проверкой объединения и суммы VT; либо отдельно принять раскрытую потерю конкретных доменов.', 'Новые обнаруженные кандидаты для точных разбиений — tail START7..15 (объединение tail=START+1..16, allocation17) и route_safety N21 (три прежних класса). Для START15 остаётся лишь один tail: само переименование не обещает ускорения. Проб и повторного full для этих изменений в текущем8-build окне нет.', 'Перед принятием E policy нужен повторный covers-аудит финального source fix и завершённый prefix-contract audit; текущие результаты не дают такого GO.', 'Никаких дополнительных удалений/переносов для достижения метрики не сделано. У разбиений число', 'моделей и удерживаемых результатов растёт, поэтому max VT и суммарная стоимость контролируются вместе.', '', 'Локальные проверки:69 lane unit tests,6 report fixtures, Python/Bash syntax, source/domain audits,', 'git diff --check для кода/отчёта и заданный rustfmt-check — PASS. Literal TSV exports сохраняют пустые конечные поля, patch artifacts — пробелы context lines; они исключены из whitespace-check без изменения данных. Локальных rustc/cargo/Kani/CBMC не было.', 'Все commits `[skip ci]`; normal push только экспериментальной ветки, Actions/CircleCI не запускались.', '', f"Отчёт сформирован {datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M UTC')}; окно сессии01:08–07:08 UTC.", '']
    p.write_text(text+'<!-- RUN-RESULTS -->\n\n'+'\n'.join(a))
    print('Final report rendered; statuses preserved, no proof acceptance inferred.')

if __name__=='__main__':main()
